command:
/**
 * Vagabond — Cone Animation (for Automated Animations)
 * Plays a fixed-length cone from the attacker toward its targets, instead of AA's
 * range clip that stretches all the way to each target.
 *
 * In an AA entry: Macro section ON, "Run macro only" (playWhen 2),
 * Name = Compendium.vagabond.fx-macros.Macro.VgbdConeAnimAA01
 * Args = file, length[, width[, color]]   e.g.  jb2a.breath_weapons.fire.cone.orange.01, 15
 *   file   = Sequencer DB key or file path
 *   length = cone length in feet (default 15)
 *   width  = optional cone width in feet (empty keeps the clip's shape)
 *   color  = optional recolor: hue shift in degrees (255 turns orange fire purple) or #rrggbb tint
 *            e.g.  jb2a.breath_weapons.fire.cone.orange.01, 15, , 255
 * Sound = the entry's Primary sound ("Run macro only" skips AA's own sound); a
 * Sequencer DB key whose module is inactive (e.g. psfx.*) is skipped.
 */
// AA passes `args`; run by hand (Execute) there is none, so do nothing
const aaArgs = typeof args !== 'undefined' ? args : (scope?.args ?? []);
const [, handler, userArgs = []] = aaArgs ?? [];
const [file, length, width, color] = Array.isArray(userArgs) ? userArgs : [userArgs];
if (!handler?.sourceToken || !file) return;
await game.vagabond.fx.cone({
  source: handler.sourceToken,
  targets: handler.allTargets ?? [],
  file: String(file).trim(),
  length: Number(length) || 15,
  width: Number(width) || undefined,
  color: color || undefined,
  sound: handler.animationData?.primary?.sound,
});
